<?php require_once '../config.php';require_admin();$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){$email=trim($_POST['email']??'');$pass=$_POST['password']??'';$img='default.svg';
try{if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Email không hợp lệ.');if(strlen($pass)<6)throw new RuntimeException('Mật khẩu tối thiểu 6 ký tự.');if(!empty($_FILES['image']['name']))$img=saveImage($_FILES['image']);$s=$pdo->prepare('INSERT INTO Users(admin_email,admin_password,images) VALUES(?,?,?)');$s->execute([$email,password_hash($pass,PASSWORD_DEFAULT),$img]);$_SESSION['flash']='Đã thêm người dùng thành công.';header('Location: index.php');exit;}catch(Throwable $e){$err=$e instanceof PDOException?'Email đã tồn tại.':$e->getMessage();}}
function saveImage($f){if($f['error']!==UPLOAD_ERR_OK||$f['size']>3145728)throw new RuntimeException('Ảnh lỗi hoặc vượt quá 3MB.');$m=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$t=['image/jpeg'=>'jpg','image/png'=>'png','image/gif'=>'gif','image/webp'=>'webp'];if(!isset($t[$m]))throw new RuntimeException('Chỉ nhận JPG, PNG, GIF, WEBP.');$n=bin2hex(random_bytes(12)).'.'.$t[$m];if(!move_uploaded_file($f['tmp_name'],__DIR__.'/../uploads/'.$n))throw new RuntimeException('Không lưu được ảnh.');return $n;}
?>
<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Thêm user</title><link rel="stylesheet" href="../assets/style.css"></head><body><main class="formpage"><a href="index.php">← Quay lại</a><section class="panel"><small>ADMIN / USERS</small><h1>Thêm người dùng</h1><?php if($err):?><div class="alert"><?=e($err)?></div><?php endif;?><form method="post" enctype="multipart/form-data"><label>Email</label><input type="email" name="email" required><label>Mật khẩu</label><input type="password" name="password" minlength="6" required><label>Ảnh đại diện</label><input type="file" name="image" accept="image/*"><div class="actions"><button class="primary">Lưu người dùng</button><a class="button" href="index.php">Hủy</a></div></form></section></main></body></html>
